export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('invalid source');
  if(!Array.isArray(edits))throw Error('invalid edits');
  for(const edit of edits)checkEdit(source,edit);
  const sorted=edits.map((edit,index)=>({edit,index})).sort((a,b)=>{
    if(a.edit.start!==b.edit.start)return a.edit.start-b.edit.start;
    return a.edit.end-b.edit.end;
  });
  for(let i=1;i<sorted.length;i++){
    const prev=sorted[i-1].edit;
    const cur=sorted[i].edit;
    const prevEmpty=prev.start===prev.end;
    const curEmpty=cur.start===cur.end;
    if(prevEmpty&&curEmpty){
      if(prev.start===cur.start)throw Error('conflicting edits');
      continue;
    }
    if(prevEmpty!==curEmpty){
      const insertion=prevEmpty?prev:cur;
      const range=prevEmpty?cur:prev;
      if(insertion.start>=range.start&&insertion.start<=range.end)throw Error('conflicting edits');
      continue;
    }
    if(cur.start<prev.end)throw Error('conflicting edits');
  }
  let result='';
  let cursor=0;
  for(const {edit} of sorted){
    result+=source.slice(cursor,edit.start)+edit.after;
    cursor=edit.end;
  }
  result+=source.slice(cursor);
  return {text:result,applied:edits.length};
}
async function runCli(){
  const args=process.argv.slice(2);
  if(args.length!==1)throw Error('expected exactly one argument');
  const {readFile}=await import('node:fs/promises');
  const raw=await readFile(args[0],'utf8');
  const data=JSON.parse(raw);
  const result=applyTransaction(data.source,data.edits);
  process.stdout.write(JSON.stringify(result)+'\n');
}
const isMain=typeof process!=='undefined'&&process.argv[1]&&import.meta.url===`file://${process.argv[1]}`;
if(isMain){
  runCli().catch(err=>{
    process.stderr.write(String(err&&err.message?err.message:err)+'\n');
    process.exit(2);
  });
}

